// xemu adapter (original Xbox).
// Layout:
//   Emulators/xemu/app       program files: xemu.exe + LICENSE.txt (replaced on update)
//   Emulators/xemu/data      xemu.toml (passed with -config_path), xemu.log (written to the
//                            working directory), omnideck-gamecfg/<game>.toml per-game configs
//   Saves/xemu/eeprom.bin    Xbox EEPROM (sys.files.eeprom_path; generated by xemu when missing)
//   Saves/xemu/screenshots   general.screenshot_dir
//   BIOS/xbox                user-supplied MCPX boot ROM, flash BIOS and HDD image (qcow2).
//                            The HDD image also holds game saves and xemu snapshots.
//   %APPDATA%\xemu\xemu      xemu's base path (shader cache), not configurable

import { existsSync } from 'node:fs';
import { copyFile, mkdir, open, readFile, readdir, stat, writeFile } from 'node:fs/promises';
import { homedir } from 'node:os';
import { basename, dirname, extname, join } from 'node:path';
import type { BiosStatus, EmulatorManifest, EmulatorSettings, Finding, GameProfile, HardwareProfile, PerformancePreset, RendererOption, SetupImportCandidate, UniversalButton } from '@shared/models';
import manifestJson from '../manifests/xemu.json';
import type { AdapterCapabilities, AdapterPaths, ConfigInput, ConfigInspection, ConfigWriteResult, EmulatorAdapter, LaunchCommand, LaunchTarget, SmokeTestResult } from '../adapter';
import type { AppPaths } from '../../core/paths';
import type { BackupTarget } from '../../config/backups';
import { atomicWrite } from '../../config/iniFile';
import { physicalFor } from '../../controllers/translate';
import { findExeIn, resolutionScaleFor } from '../common';
import { fileVersion, isWindows } from '../../platform/powershell';
import { splitArgs } from '../pcsx2/adapter';
import { TomlDocument, checkToml, tomlEqual, type TomlTable, type TomlValue } from './toml';

export const XEMU_MANIFEST = manifestJson as unknown as EmulatorManifest;

/** display.renderer enum values (config_spec.yml). */
export const XEMU_RENDERERS: Record<string, string> = { opengl: 'OPENGL', vulkan: 'VULKAN' };

/** Sizes checked by xemu (system/vl.c qemu_init, hw/xbox/xbox.c xbox_flash_init). */
export const MCPX_SIZE = 512;
export const EEPROM_SIZE = 256;
const FLASH_KNOWN: Record<number, string> = { [256 * 1024]: '256 KB flash BIOS image', [512 * 1024]: '512 KB flash BIOS image', [1024 * 1024]: '1 MB flash BIOS image' };
const QCOW_MAGIC = 'QFI\xfb';

type Managed = [path: string[], value: TomlValue, def: TomlValue | undefined];

/** SDL3 SDL_GamepadButton indices, as stored in gamepad_mappings.controller_mapping. */
const SDL_BUTTON: Partial<Record<UniversalButton, number>> = {
  A: 0, B: 1, X: 2, Y: 3, Select: 4, Guide: 5, Start: 6, L3: 7, R3: 8, LB: 9, RB: 10,
  DPadUp: 11, DPadDown: 12, DPadLeft: 13, DPadRight: 14,
};
/** SDL3 SDL_GamepadAxis indices. */
const SDL_AXIS = { leftX: 0, leftY: 1, rightX: 2, rightY: 3, leftTrigger: 4, rightTrigger: 5 };

/** controller_mapping key -> logical universal button (ui/xemu-input.c; lshoulder = White, rshoulder = Black). */
const XBOX_PAD: [string, UniversalButton][] = [
  ['a', 'A'], ['b', 'B'], ['x', 'X'], ['y', 'Y'], ['back', 'Select'], ['guide', 'Guide'], ['start', 'Start'],
  ['lstick_btn', 'L3'], ['rstick_btn', 'R3'], ['lshoulder', 'LB'], ['rshoulder', 'RB'],
  ['dpad_up', 'DPadUp'], ['dpad_down', 'DPadDown'], ['dpad_left', 'DPadLeft'], ['dpad_right', 'DPadRight'],
];

/** Defaults of the controller_mapping table (config_spec.yml). */
const MAPPING_DEFAULTS: Record<string, number | boolean> = {
  a: 0, b: 1, x: 2, y: 3, back: 4, guide: 5, start: 6, lstick_btn: 7, rstick_btn: 8, lshoulder: 9, rshoulder: 10,
  dpad_up: 11, dpad_down: 12, dpad_left: 13, dpad_right: 14,
  axis_left_x: 0, axis_left_y: 1, axis_right_x: 2, axis_right_y: 3, axis_trigger_left: 4, axis_trigger_right: 5,
  invert_axis_left_x: false, invert_axis_left_y: false, invert_axis_right_x: false, invert_axis_right_y: false,
};

export type XboxFileKind = 'mcpx' | 'flash' | 'hdd';

export interface XboxSystemFile {
  path: string;
  sizeBytes: number;
  valid: boolean;
  description: string;
}

function isTable(v: TomlValue | undefined): v is TomlTable {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function samePath(a: string | null | undefined, b: string): boolean {
  if (!a) return false;
  const n = (s: string) => s.replace(/\//g, '\\').replace(/\\+$/, '').toLowerCase();
  return n(a) === n(b);
}

/** "true"/"false" -> boolean, integers -> number, anything else stays a string. */
function typedValue(v: string): TomlValue {
  if (v === 'true' || v === 'false') return v === 'true';
  if (/^-?\d+$/.test(v)) return parseInt(v, 10);
  return v;
}

export class XemuAdapter implements EmulatorAdapter {
  readonly manifest = XEMU_MANIFEST;
  readonly capabilities: AdapterCapabilities = {
    perGameProfiles: 'native',
    frameLimit: false,
    vsync: true,
    aspectRatios: [
      { id: 'auto', label: 'Auto (game native)' },
      { id: 'native', label: 'Native framebuffer' },
      { id: '4:3', label: '4:3' },
      { id: '16:9', label: '16:9' },
      { id: 'stretch', label: 'Stretch to window' },
    ],
    // xemu's in-game menu is opened by Guide or Back+Start (ui/xui/main.cc); it is not configurable.
    hotkeys: [],
    smokeTest: true,
    maxResolutionScale: 10,
  };

  constructor(private readonly app: AppPaths) {}

  paths(): AdapterPaths {
    return {
      app: this.app.emulatorAppDir('xemu'),
      data: this.app.emulatorDataDir('xemu'),
      saves: this.app.emulatorSaveDir('xemu'),
      bios: this.app.systemBiosDir('xbox'),
      cache: this.app.emulatorCacheDir('xemu'),
    };
  }

  configPath(): string {
    return join(this.paths().data, 'xemu.toml');
  }

  eepromPath(): string {
    return join(this.paths().saves, 'eeprom.bin');
  }

  screenshotDir(): string {
    return join(this.paths().saves, 'screenshots');
  }

  gameConfigPath(gameId: number | null): string {
    return join(this.paths().data, 'omnideck-gamecfg', `${gameId ?? 'adhoc'}.toml`);
  }

  /** SDL_GetPrefPath("xemu", "xemu") on Windows: xemu's base path when not portable (ui/xemu-settings.cc). */
  prefPath(): string {
    return join(process.env.APPDATA ?? join(homedir(), 'AppData', 'Roaming'), 'xemu', 'xemu');
  }

  async findExecutable(appDir: string): Promise<string | null> {
    return findExeIn(appDir, [/^xemu\.exe$/i, /^xemu$/]);
  }

  /** version.rc: FileVersion is the XEMU_VERSION string; falls back to "xemu_version: x" at the top of xemu.log. */
  async detectVersion(executable: string): Promise<string | null> {
    const v = await fileVersion(executable);
    const m = v ? /\d+\.\d+\.\d+/.exec(v) : null;
    if (m) return m[0];
    const log = this.logFile();
    if (log && existsSync(log)) return parseXemuVersion(await readHead(log, 2048));
    return null;
  }

  renderers(hw: HardwareProfile | null): RendererOption[] {
    const vk = hw?.graphicsApis.vulkan;
    const gl = hw?.graphicsApis.opengl;
    return [
      { id: 'vulkan', label: 'Vulkan', available: vk !== false, note: vk === false ? 'No Vulkan driver detected' : undefined },
      { id: 'opengl', label: 'OpenGL (4.0 or newer)', available: gl !== false, note: gl === false ? 'No OpenGL driver detected' : undefined },
    ];
  }

  defaultSettings(hw: HardwareProfile | null, preset: PerformancePreset): EmulatorSettings {
    const gpu = hw?.gpus[0];
    const vulkan = !!hw?.graphicsApis.vulkan && !!gpu && (gpu.vendor === 'nvidia' || gpu.vendor === 'amd');
    return {
      preset,
      resolutionScale: resolutionScaleFor(hw, preset, this.capabilities.maxResolutionScale),
      renderer: vulkan ? 'vulkan' : 'opengl',
      aspectRatio: 'auto',
      fullscreen: true,
      frameLimit: true,
      vsync: preset !== 'performance',
      advanced: {},
    };
  }

  configTargets(): BackupTarget[] {
    return [{ root: this.paths().data, path: this.configPath() }];
  }

  private async ensureDirs(): Promise<void> {
    const p = this.paths();
    for (const d of [p.app, p.data, p.saves, this.screenshotDir(), p.bios, p.cache]) await mkdir(d, { recursive: true });
  }

  // -------------------------------------------------------------------------
  // System files (BIOS/xbox)
  // -------------------------------------------------------------------------

  /** Classifies the files in BIOS/xbox (non-recursive), valid candidates first. */
  async systemFiles(): Promise<Record<XboxFileKind, XboxSystemFile[]> & { eeprom: string | null }> {
    const out: Record<XboxFileKind, XboxSystemFile[]> & { eeprom: string | null } = { mcpx: [], flash: [], hdd: [], eeprom: null };
    const dir = this.paths().bios;
    if (!existsSync(dir)) return out;
    for (const f of (await readdir(dir)).sort()) {
      const full = join(dir, f);
      const st = await stat(full).catch(() => null);
      if (!st?.isFile()) continue;
      const ext = extname(f).toLowerCase();
      const size = st.size;
      if (ext === '.qcow2' || /hdd/i.test(f)) {
        const head = await readHead(full, 4, 'latin1');
        const valid = ext === '.qcow2' && head === QCOW_MAGIC;
        out.hdd.push({ path: full, sizeBytes: size, valid, description: valid ? `Xbox hard disk image (qcow2, ${(size / 1024 ** 3).toFixed(1)} GB on disk)` : 'Not a qcow2 hard disk image (bad header or extension)' });
        continue;
      }
      if (size === EEPROM_SIZE || /eeprom/i.test(f)) {
        if (size === EEPROM_SIZE) out.eeprom = out.eeprom ?? full;
        continue;
      }
      if (size === MCPX_SIZE || /mcpx/i.test(f)) {
        const valid = size === MCPX_SIZE;
        out.mcpx.push({ path: full, sizeBytes: size, valid, description: valid ? 'MCPX boot ROM (512 bytes)' : `Not an MCPX boot ROM: ${size} bytes, expected 512` });
        continue;
      }
      if (ext === '.bin' || ext === '.rom') {
        const valid = size > 0 && size % 65536 === 0 && size <= 1024 * 1024;
        out.flash.push({ path: full, sizeBytes: size, valid, description: valid ? FLASH_KNOWN[size] ?? `Flash BIOS image (${size / 1024} KB)` : `Not a flash BIOS image: ${size} bytes (expected 256 KB or 1 MB)` });
      }
    }
    for (const k of ['mcpx', 'flash', 'hdd'] as const) out[k].sort((a, b) => Number(b.valid) - Number(a.valid));
    return out;
  }

  async biosStatus(): Promise<BiosStatus[]> {
    const files = await this.systemFiles();
    const dir = this.paths().bios;
    const entry = (kind: XboxFileKind, label: string, missing: string, invalid: string, found: (f: XboxSystemFile) => string): BiosStatus => {
      const list = files[kind];
      const ok = list.find((f) => f.valid);
      const status: BiosStatus['status'] = ok ? 'found' : list.length ? 'invalid' : 'missing';
      return {
        systemId: 'xbox', systemName: 'Xbox', label, required: true, requirementKind: 'bios', emulatorId: 'xemu',
        expectedLocation: dir, status, files: list,
        note: ok ? found(ok) : list.length ? invalid : missing,
      };
    };
    const all = [
      entry('mcpx', 'Xbox MCPX boot ROM', `Place the 512-byte MCPX boot ROM dumped from your own Xbox (e.g. mcpx_1.0.bin) in ${dir}. OmniDeck never downloads it.`, 'The file in this folder is not 512 bytes, so xemu rejects it ("Invalid BootROM file").', (f) => `Using ${basename(f.path)}.`),
      entry('flash', 'Xbox flash BIOS', `Place the flash BIOS image (256 KB or 1 MB .bin) dumped from your own Xbox in ${dir}. OmniDeck never downloads it.`, 'The .bin file in this folder is not a valid flash image size (a multiple of 64 KB, normally 256 KB or 1 MB).', (f) => `Using ${basename(f.path)}.`),
      entry('hdd', 'Xbox hard disk image', `Place your own xemu hard disk image (.qcow2) in ${dir}. It holds the dashboard and your game saves. OmniDeck never downloads it.`, 'The hard disk file in this folder is not a qcow2 image (it must start with the "QFI\\xfb" header).', (f) => `Using ${basename(f.path)}. Your game saves and xemu snapshots live inside this image: back it up.`),
    ];
    // The launch preflight checks the first entry for the system, so a missing or invalid file is listed first.
    return all.sort((a, b) => Number(a.status === 'found') - Number(b.status === 'found'));
  }

  // -------------------------------------------------------------------------
  // Configuration
  // -------------------------------------------------------------------------

  /** Keys that keep launches non-interactive and paths that point into OmniDeck folders. */
  async pathValues(): Promise<Managed[]> {
    const files = await this.systemFiles();
    const v: Managed[] = [
      // general.show_welcome=true opens the First Boot window AND disables autostart / skips the flash ROM (system/vl.c).
      [['general', 'show_welcome'], false, true],
      // Windows update check popup (ui/xui/main.cc, update.cc).
      [['general', 'updates', 'check'], false, true],
      [['sys', 'files', 'eeprom_path'], this.eepromPath(), ''],
      [['general', 'screenshot_dir'], this.screenshotDir(), ''],
    ];
    const pick = (k: XboxFileKind) => files[k].find((f) => f.valid)?.path;
    const mcpx = pick('mcpx');
    const flash = pick('flash');
    const hdd = pick('hdd');
    if (mcpx) v.push([['sys', 'files', 'bootrom_path'], mcpx, '']);
    if (flash) v.push([['sys', 'files', 'flashrom_path'], flash, '']);
    if (hdd) v.push([['sys', 'files', 'hdd_path'], hdd, '']);
    return v;
  }

  graphicsValues(s: EmulatorSettings): Managed[] {
    const scale = Math.max(1, Math.min(this.capabilities.maxResolutionScale, Math.round(s.resolutionScale)));
    const aspect = s.aspectRatio === '4:3' ? '4x3' : s.aspectRatio === '16:9' ? '16x9' : s.aspectRatio === 'native' ? 'native' : 'auto';
    return [
      [['display', 'renderer'], XEMU_RENDERERS[s.renderer] ?? 'OPENGL', 'OPENGL'],
      [['display', 'quality', 'surface_scale'], scale, 1],
      [['display', 'window', 'fullscreen_on_startup'], s.fullscreen, false],
      [['display', 'window', 'vsync'], s.vsync, true],
      [['display', 'ui', 'fit'], s.aspectRatio === 'stretch' ? 'stretch' : 'scale', 'scale'],
      [['display', 'ui', 'aspect_ratio'], aspect, 'auto'],
    ];
  }

  /** "section.sub.key" advanced values -> TOML paths. */
  advancedValues(adv: Record<string, string>): Managed[] {
    return Object.entries(adv)
      .filter(([k]) => /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$/.test(k))
      .map(([k, v]): Managed => [k.split('.'), typedValue(v), undefined]);
  }

  /** controller_mapping + rumble values derived from the universal profile. */
  controllerMapping(input: ConfigInput): { mapping: Record<string, number | boolean>; rumble: boolean; notes: string[] } {
    const c = input.controller;
    const notes: string[] = [];
    const mapping: Record<string, number | boolean> = {};
    for (const [key, logical] of XBOX_PAD) {
      const phys = physicalFor(c, 'xbox', logical);
      const idx = SDL_BUTTON[phys];
      if (idx === undefined) {
        notes.push(`xemu can only map Xbox ${key} to a gamepad button; ${phys} is an axis, so ${key} keeps its default.`);
        mapping[key] = MAPPING_DEFAULTS[key];
      } else mapping[key] = idx;
    }
    const trig = (logical: UniversalButton, def: number) => {
      const p = physicalFor(c, 'xbox', logical);
      if (p === 'LT') return SDL_AXIS.leftTrigger;
      if (p === 'RT') return SDL_AXIS.rightTrigger;
      if (p !== logical) notes.push(`xemu maps triggers to trigger axes only; ${logical} keeps its default.`);
      return def;
    };
    mapping.axis_trigger_left = trig('LT', SDL_AXIS.leftTrigger);
    mapping.axis_trigger_right = trig('RT', SDL_AXIS.rightTrigger);
    const stick = (side: 'left' | 'right') => {
      const L = side === 'left' ? 'LeftStick' : 'RightStick';
      const axisFor = (logical: UniversalButton, dir: 'x' | 'y'): { axis: number; invert: boolean } => {
        const p = physicalFor(c, 'xbox', logical);
        const m = /^(Left|Right)Stick(Up|Down|Left|Right)$/.exec(p);
        const defAxis = side === 'left' ? (dir === 'x' ? SDL_AXIS.leftX : SDL_AXIS.leftY) : dir === 'x' ? SDL_AXIS.rightX : SDL_AXIS.rightY;
        if (!m || (dir === 'y') !== (m[2] === 'Up' || m[2] === 'Down')) {
          if (p !== logical) notes.push(`xemu maps stick axes only to stick axes on the same orientation; ${logical} keeps its default.`);
          return { axis: defAxis, invert: false };
        }
        const axis = m[1] === 'Left' ? (dir === 'x' ? SDL_AXIS.leftX : SDL_AXIS.leftY) : dir === 'x' ? SDL_AXIS.rightX : SDL_AXIS.rightY;
        return { axis, invert: m[2] === 'Down' || m[2] === 'Right' };
      };
      const x = axisFor(`${L}Left` as UniversalButton, 'x');
      const y = axisFor(`${L}Up` as UniversalButton, 'y');
      mapping[`axis_${side}_x`] = x.axis;
      mapping[`axis_${side}_y`] = y.axis;
      mapping[`invert_axis_${side}_x`] = x.invert;
      mapping[`invert_axis_${side}_y`] = y.invert;
    };
    stick('left');
    stick('right');
    return { mapping, rumble: c.rumble, notes: [...new Set(notes)] };
  }

  private async loadDoc(path: string): Promise<TomlDocument> {
    if (!existsSync(path)) return TomlDocument.empty();
    return TomlDocument.parse(await readFile(path, 'utf8'));
  }

  /** Writes managed values. A value equal to xemu's default is only written when the key is present with another value (xemu drops default values on save). */
  private applyManaged(doc: TomlDocument, values: Managed[], changed: string[]): void {
    for (const [p, v, def] of values) {
      const cur = doc.get(p);
      if (cur === undefined && tomlEqual(v, def)) continue;
      if (doc.set(p, v)) changed.push(`xemu.toml: ${p.join('.')} = ${typeof v === 'object' ? JSON.stringify(v) : v}`);
    }
  }

  private applyController(doc: TomlDocument, input: ConfigInput, changed: string[], notes: string[]): void {
    const { mapping, rumble, notes: n } = this.controllerMapping(input);
    notes.push(...n);
    // auto_bind (default true) binds the first connected controller to port 1 (ui/xemu-input.c).
    if (doc.get(['input', 'auto_bind']) === false && doc.set(['input', 'auto_bind'], true)) changed.push('xemu.toml: input.auto_bind = true');
    // The deprecated global allow_vibration=false disables rumble on every controller at load (xemu-settings.cc).
    if (rumble && doc.get(['input', 'allow_vibration']) === false && doc.set(['input', 'allow_vibration'], true)) changed.push('xemu.toml: input.allow_vibration = true');
    if (doc.hasArrayTables(['input', 'gamepad_mappings'])) {
      notes.push('xemu.toml lists controllers as [[input.gamepad_mappings]] sections; OmniDeck leaves those hand-edited entries unchanged.');
      return;
    }
    const current = doc.get(['input', 'gamepad_mappings']);
    const list = Array.isArray(current) ? current.filter(isTable) : [];
    if (!list.length) {
      notes.push('xemu stores button mappings per controller (by SDL GUID) once it has seen the controller. Start a game once with the controller connected, then apply the controller settings again to transfer remaps and rumble.');
    }
    const next: TomlValue[] = (Array.isArray(current) ? current : []).map((el) => {
      if (!isTable(el)) return el;
      const e: TomlTable = JSON.parse(JSON.stringify(el));
      if (e.enable_rumble !== undefined || !rumble) e.enable_rumble = rumble;
      const cm: TomlTable = isTable(e.controller_mapping) ? e.controller_mapping : {};
      for (const [k, v] of Object.entries(mapping)) {
        if (cm[k] === undefined && v === MAPPING_DEFAULTS[k]) continue;
        cm[k] = v;
      }
      if (Object.keys(cm).length) e.controller_mapping = cm;
      return e;
    });
    if (list.length && doc.set(['input', 'gamepad_mappings'], next)) changed.push(`xemu.toml: input.gamepad_mappings (${list.length} controller${list.length === 1 ? '' : 's'})`);
    if (input.controller.deviceIndex > 0) notes.push('xemu binds controllers to ports itself (the first connected controller goes to port 1); OmniDeck cannot pick a specific device.');
    notes.push('xemu has no stick deadzone setting; the profile deadzone is not applied.');
    const menu = input.hotkeys.bindings.menu;
    if (!(menu === 'Guide' || (input.hotkeys.modifier === 'Select' && menu === 'Start') || (input.hotkeys.modifier === 'Start' && menu === 'Select'))) {
      notes.push('xemu\'s menu opens with Guide or Back+Start; it cannot be remapped to the OmniDeck menu hotkey.');
    }
  }

  async applyConfig(input: ConfigInput, scope: 'all' | 'controller' | 'graphics' | 'paths'): Promise<ConfigWriteResult> {
    await this.ensureDirs();
    const changed: string[] = [];
    const notes: string[] = [];
    const path = this.configPath();
    const doc = await this.loadDoc(path);
    const existed = existsSync(path);
    if (scope === 'all' || scope === 'paths') {
      notes.push(...(await this.seedEeprom()));
      this.applyManaged(doc, await this.pathValues(), changed);
      const missing = (await this.biosStatus()).filter((b) => b.status !== 'found');
      for (const b of missing) notes.push(`${b.label}: ${b.note}`);
    }
    if (scope === 'all' || scope === 'graphics') {
      this.applyManaged(doc, [...this.graphicsValues(input.settings), ...this.advancedValues(input.settings.advanced)], changed);
    }
    if (scope === 'all' || scope === 'controller') this.applyController(doc, input, changed, notes);
    if (!existed || changed.length) await atomicWrite(path, doc.toString());
    return { changed, notes };
  }

  /** Copies a user's eeprom.bin from the BIOS folder into Saves the first time (never overwrites). */
  private async seedEeprom(): Promise<string[]> {
    if (existsSync(this.eepromPath())) return [];
    const files = await this.systemFiles();
    if (!files.eeprom) return [];
    await mkdir(this.paths().saves, { recursive: true });
    await copyFile(files.eeprom, this.eepromPath());
    return [`Copied ${basename(files.eeprom)} from the BIOS folder to ${this.eepromPath()}.`];
  }

  async inspectConfig(): Promise<ConfigInspection> {
    const path = this.configPath();
    const exists = existsSync(path);
    const text = exists ? await readFile(path, 'utf8').catch(() => '') : '';
    const fmt = exists ? checkToml(text) : { ok: false, issues: ['File does not exist'] };
    const files: ConfigInspection['files'] = [{ label: 'xemu.toml', path, exists, parseOk: exists && fmt.ok, issues: fmt.issues }];
    const drift: ConfigInspection['drift'] = [];
    if (exists && fmt.ok) {
      const doc = TomlDocument.parse(text);
      for (const [p, expected, def] of await this.pathValues()) {
        const raw = doc.get(p);
        const actual = raw === undefined ? def : raw;
        const key = p.join('.');
        const same = typeof expected === 'string' && typeof actual === 'string' && expected.length > 0 ? samePath(actual, expected) : tomlEqual(actual, expected);
        if (same) continue;
        const critical = key === 'general.show_welcome' || (key.startsWith('sys.files.') && key !== 'sys.files.eeprom_path');
        drift.push({ file: path, key, expected: String(expected), actual: raw === undefined ? null : String(raw), critical });
      }
    }
    return { files, drift };
  }

  /** Per-game overrides as TOML values. */
  profileOverrides(base: EmulatorSettings, profile: GameProfile): Managed[] {
    const o = profile.overrides;
    const merged: EmulatorSettings = { ...base, ...(o as Partial<EmulatorSettings>), advanced: {} };
    const g = this.graphicsValues(merged);
    const pick = (...keys: string[]) => g.filter(([p]) => keys.includes(p[p.length - 1]));
    const out: Managed[] = [];
    if (o.renderer !== undefined) out.push(...pick('renderer'));
    if (o.resolutionScale !== undefined) out.push(...pick('surface_scale'));
    if (o.aspectRatio !== undefined) out.push(...pick('fit', 'aspect_ratio'));
    if (o.vsync !== undefined) out.push(...pick('vsync'));
    if (o.fullscreen !== undefined) out.push(...pick('fullscreen_on_startup'));
    out.push(...this.advancedValues(o.advanced ?? {}));
    return out;
  }

  async buildLaunch(target: LaunchTarget, executable: string, settings: EmulatorSettings, profile: GameProfile | null, _version: string | null): Promise<LaunchCommand> {
    const p = this.paths();
    const notes: string[] = [];
    let config = this.configPath();
    const overrides = profile ? this.profileOverrides(settings, profile) : [];
    const gameCfg = overrides.length ? this.gameConfigPath(target.gameId) : null;
    if (gameCfg) {
      config = gameCfg;
      notes.push(`Per-game profile applied with -config_path (${overrides.length} overrides on top of xemu.toml); settings changed inside xemu during this session are kept in that file only.`);
    }
    const prepare = async () => {
      // BIOS files may have been added since the last applyConfig: re-point sys.files.* before each launch.
      await this.ensureDirs();
      await this.seedEeprom();
      const doc = await this.loadDoc(this.configPath());
      const changed: string[] = [];
      this.applyManaged(doc, await this.pathValues(), changed);
      if (changed.length || !existsSync(this.configPath())) await atomicWrite(this.configPath(), doc.toString());
      if (gameCfg) {
        for (const [path, v] of overrides) doc.set(path, v);
        await atomicWrite(gameCfg, doc.toString());
      }
    };
    // -config_path is consumed in ui/xemu.c main(); -full-screen is the QEMU option; -dvd_path overrides
    // sys.files.dvd_path (system/vl.c). A bare positional argument would be attached as a hard disk.
    const args = ['-config_path', config];
    if (settings.fullscreen) args.push('-full-screen');
    if (profile?.customArgs) args.push(...splitArgs(profile.customArgs));
    args.push('-dvd_path', target.path);
    // xemu.log is opened relative to the working directory (ui/xemu.c), so run from the data folder.
    return { command: executable, args, targetArgs: 2, cwd: p.data, logFile: this.logFile(), prepare, notes };
  }

  buildUiLaunch(executable: string): LaunchCommand {
    return { command: executable, args: ['-config_path', this.configPath()], cwd: this.paths().data, logFile: this.logFile(), notes: [] };
  }

  async smokeTest(executable: string): Promise<SmokeTestResult> {
    const checks: SmokeTestResult['checks'] = [];
    const present = existsSync(executable);
    checks.push({ label: 'Executable present', ok: present, detail: executable });
    if (!present) return { ran: true, ok: false, checks };
    const mz = (await readHead(executable, 2, 'latin1')) === 'MZ';
    checks.push({ label: 'Executable is a Windows program', ok: mz || !/\.exe$/i.test(executable), detail: mz ? 'PE header found' : 'No "MZ" header: the download may be incomplete' });
    const insp = await this.inspectConfig();
    const cfg = insp.files[0];
    checks.push({ label: 'xemu.toml parses', ok: !cfg.exists || cfg.parseOk, detail: cfg.exists ? (cfg.parseOk ? 'OK' : `${cfg.issues.join('; ')}: xemu shows an error dialog and exits with a broken xemu.toml`) : 'Not created yet (written on first configuration)' });
    const welcome = insp.drift.find((d) => d.key === 'general.show_welcome');
    checks.push({ label: 'First-boot window disabled', ok: !cfg.exists || !welcome, detail: welcome ? 'general.show_welcome is not false: xemu would open its First Boot window and not start the game' : 'OK' });
    // xemu has no flag that checks itself and exits without creating its SDL/OpenGL window
    // (-version is parsed by QEMU after the window exists), so it is never executed here.
    checks.push({ label: 'Executable starts', ok: true, detail: isWindows ? 'Skipped: xemu has no non-interactive self-test option' : 'Skipped: only possible on Windows' });
    return { ran: false, ok: checks.every((c) => c.ok), checks };
  }

  async validateEnvironment(hw: HardwareProfile | null, executable: string | null): Promise<Finding[]> {
    const out: Finding[] = [];
    const subject = { kind: 'emulator' as const, id: 'xemu', label: 'xemu' };
    if (hw && hw.cpu.features.length && !hw.cpu.features.includes('avx2')) {
      out.push({
        id: 'xemu.avx2', checkId: 'xemu.cpu', category: 'emulators', severity: 'problem', title: 'CPU without AVX2',
        detail: 'Official xemu x86_64 release builds are compiled for x86-64-v3 (-Dx86_version=3 in .github/workflows/build-windows.yml), which needs AVX2. xemu will crash with an illegal-instruction error on this CPU.', subject,
        evidence: [`CPU: ${hw.cpu.model}`, `CPU features: ${hw.cpu.features.join(', ')}`], confidence: 'high', repair: null,
        manualSteps: ['Use the "-dbg" build from xemu\'s GitHub release page as a custom executable (it is built without that requirement, but runs slower).'],
      });
    }
    if (hw && hw.graphicsApis.opengl === false && hw.graphicsApis.vulkan === false) {
      out.push({
        id: 'xemu.gl', checkId: 'xemu.graphics', category: 'graphics', severity: 'problem', title: 'No OpenGL 4.0 or Vulkan driver detected',
        detail: 'xemu needs an OpenGL 4.0 context for its window even with the Vulkan renderer ("Unable to create OpenGL context", ui/xemu.c).', subject,
        evidence: hw.graphicsApis.notes, confidence: 'medium', repair: null, manualSteps: ['Install the latest graphics driver from your GPU vendor.'],
      });
    }
    for (const b of await this.biosStatus()) {
      if (b.status === 'found') continue;
      out.push({
        id: `xemu.bios.${b.label}`, checkId: 'xemu.bios', category: 'bios', severity: 'problem', title: `${b.label} ${b.status === 'invalid' ? 'is not valid' : 'is missing'}`,
        detail: b.note, subject, evidence: [b.expectedLocation, ...b.files.map((f) => `${f.path}: ${f.description}`)], confidence: 'high', repair: null,
        manualSteps: ['Copy the file dumped from your own Xbox into the BIOS folder (Settings > BIOS & Firmware).'],
      });
    }
    if (executable && existsSync(join(dirname(executable), 'xemu.toml'))) {
      out.push({
        id: 'xemu.portable', checkId: 'xemu.paths', category: 'emulators', severity: 'info', title: 'xemu.toml next to xemu.exe (portable mode)',
        detail: 'A xemu.toml next to xemu.exe switches xemu to portable mode: its shader cache moves into the program folder. OmniDeck always passes its own xemu.toml with -config_path, so your settings are not affected.', subject,
        evidence: [join(dirname(executable), 'xemu.toml')], confidence: 'high', repair: null, manualSteps: [],
      });
    }
    return out;
  }

  saveLocations(): { label: string; path: string }[] {
    return [
      { label: 'Xbox hard disk image (.qcow2 in the BIOS folder: game saves and snapshots)', path: this.paths().bios },
      { label: 'EEPROM', path: this.eepromPath() },
      { label: 'Screenshots', path: this.screenshotDir() },
    ];
  }

  logFile(): string | null {
    return join(this.paths().data, 'xemu.log');
  }

  cacheDirs(): { label: string; path: string }[] {
    // ui/xemu-settings.cc xemu_settings_get_base_path + hw/xbox/nv2a/pgraph/gl/shaders.c: <base>/shaders and <base>/shader_cache_list.
    return [{ label: 'OpenGL shader cache (xemu base folder)', path: join(this.prefPath(), 'shaders') }];
  }

  async recoverSession(): Promise<string[]> {
    // Per-game settings use their own -config_path file; xemu.toml is never modified for a session.
    return [];
  }

  async detectExistingSetups(): Promise<SetupImportCandidate[]> {
    const out: SetupImportCandidate[] = [];
    const home = homedir();
    const appData = process.env.APPDATA ?? join(home, 'AppData', 'Roaming');
    const dirs = [
      this.prefPath(),
      'C:\\xemu', 'D:\\xemu', 'C:\\Emulators\\xemu', 'D:\\Emulators\\xemu',
      join(home, 'xemu'), join(home, 'Desktop', 'xemu'), join(home, 'Documents', 'xemu'), join(home, 'Downloads', 'xemu'),
      join(appData, 'emudeck', 'Emulators', 'xemu'),
      'C:\\Program Files\\xemu',
    ];
    const seen = new Set<string>();
    for (const dir of dirs) {
      const key = dir.toLowerCase().replace(/[\\/]+$/, '');
      if (seen.has(key) || !existsSync(dir)) continue;
      seen.add(key);
      const exe = await this.findExecutable(dir);
      const toml = join(dir, 'xemu.toml');
      const hasToml = existsSync(toml);
      if (!exe && !hasToml) continue;
      const details = [exe ? `Executable: ${exe}` : 'No xemu.exe in this folder', hasToml ? `Settings: ${toml}` : 'No xemu.toml'];
      const biosDirs: { dir: string; systemId: string }[] = [];
      if (hasToml) {
        const doc = await this.loadDoc(toml).catch(() => TomlDocument.empty());
        for (const [k, label] of [['bootrom_path', 'MCPX boot ROM'], ['flashrom_path', 'Flash BIOS'], ['hdd_path', 'Hard disk image'], ['eeprom_path', 'EEPROM']] as const) {
          const v = doc.get(['sys', 'files', k]);
          if (typeof v !== 'string' || !v) continue;
          details.push(`${label}: ${v}${existsSync(v) ? '' : ' (missing)'}`);
          if (existsSync(v) && !biosDirs.some((b) => samePath(b.dir, dirname(v)))) biosDirs.push({ dir: dirname(v), systemId: 'xbox' });
        }
      }
      out.push({
        id: `xemu:${key}`, source: 'xemu', label: `xemu (${dir})`, path: dir, details,
        importable: { settings: hasToml, saves: false, bios: biosDirs.length > 0, romPaths: false, useInstallation: !!exe },
        romPaths: [],
        biosDirs,
      });
    }
    return out;
  }

  async prepareInstall(_appDir: string): Promise<string[]> {
    await mkdir(this.paths().data, { recursive: true });
    await writeFile(join(this.paths().data, 'README-OmniDeck.txt'), 'This folder holds xemu.toml, which OmniDeck passes to xemu with -config_path, and xemu.log. The MCPX boot ROM, flash BIOS and hard disk image live in the OmniDeck BIOS\\xbox folder; eeprom.bin lives in Saves\\xemu.\r\n');
    return [];
  }

  /** Files xemu keeps next to xemu.exe in portable mode (xemu.toml present there): kept across updates, never deleted. */
  persistentAppPaths(): string[] {
    return ['xemu.toml', 'eeprom.bin', 'shaders', 'shader_cache_list', 'xemu.log'];
  }
}

/** "xemu_version: 0.8.136" (ui/xemu.c main) -> "0.8.136". */
export function parseXemuVersion(text: string): string | null {
  const m = /xemu_version:\s*v?(\d+\.\d+\.\d+)/.exec(text);
  return m ? m[1] : null;
}

async function readHead(path: string, bytes: number, encoding: BufferEncoding = 'utf8'): Promise<string> {
  const fh = await open(path, 'r').catch(() => null);
  if (!fh) return '';
  try {
    const buf = Buffer.alloc(bytes);
    const { bytesRead } = await fh.read(buf, 0, bytes, 0);
    return buf.subarray(0, bytesRead).toString(encoding);
  } finally {
    await fh.close();
  }
}
